// function calc(a, op, b) mein do numbers aur operator do
// "+", "-", "*", "/" ke liye calculate karo
// Division by zero handle karo

solution:
function calc(a, op, b) {
  switch (op) {
    case "+": return a + b
    case "-": return a - b
    case "*": return a * b
    case "/":
      if (b === 0) return "Cannot divide by zero"
      return a / b
    default: return "Invalid operator"
  }
}
